    }

    public override Core Lift(ulong value) {
        return new Core(value);
    }

    public override Core Read(BigEndianStream stream) {
        return Lift(stream.ReadULong());
    }

    public override int AllocationSize(Core value) {
        return 8;
    }

    public override void Write(Core value, BigEndianStream stream) {
        stream.WriteULong(Lower(value));
    }
