/// <summary>
/// Something the user did in the window. Most are one core event, and Report
/// is four ([`UiEvent::events`]); the core decides what each means in the
/// state it is in.
/// </summary>
public record UiEvent {
    
    /// <summary>
    /// "Sign in with your browser".
    /// </summary>
    public record SignIn: UiEvent {}
    
    
    /// <summary>
    /// "Cancel", while signing in.
    /// </summary>
    public record CancelSignIn: UiEvent {}
    
    
    /// <summary>
    /// "Try again", after a start-up check that could not finish.
    /// </summary>
    public record RetryRestore: UiEvent {}
    
    
    /// <summary>
    /// "Sign out again", after a sign-out that left something behind.
    /// </summary>
    public record RetrySignOut: UiEvent {}
    
    
    /// <summary>
    /// "Sign out", from the account screen.
    /// </summary>
    public record SignOut: UiEvent {}
    
    
    /// <summary>
    /// A tab of the navigation view.
    /// </summary>
    public record OpenTab (
        TabView Tab
    ) : UiEvent {}
    
    /// <summary>
    /// The back button.
    /// </summary>
    public record Back: UiEvent {}
    
    
    /// <summary>
    /// Refresh the screen showing.
    /// </summary>
    public record Refresh: UiEvent {}
    
    
    /// <summary>
    /// The notice over every screen was dismissed.
    /// </summary>
    public record DismissNotice: UiEvent {}
    
    
    /// <summary>
    /// The window was shown or hidden (minimised, or closed to the tray).
    /// </summary>
    public record WindowVisible (
        bool Visible
    ) : UiEvent {}
    
    /// <summary>
    /// Open another workspace from the switcher.
    /// </summary>
    public record SelectWorkspace (
        string WorkspaceId
    ) : UiEvent {}
    
    /// <summary>
    /// The overview's "Open the web dashboard" card.
    /// </summary>
    public record OpenFinishSetup: UiEvent {}
    
    
    /// <summary>
    /// Open a conversation. The core marks it read as it opens it.
    /// </summary>
    public record OpenThread (
        string ThreadKey
    ) : UiEvent {}
    
    /// <summary>
    /// Read the open conversation's older events.
    /// </summary>
    public record LoadOlder: UiEvent {}
    
    
    /// <summary>
    /// The inbox's search box changed.
    /// </summary>
    public record Search (
        string Query
    ) : UiEvent {}
    
    /// <summary>
    /// The inbox's search box was cleared.
    /// </summary>
    public record ClearSearch: UiEvent {}
    
    
    /// <summary>
    /// Open a call.
    /// </summary>
    public record OpenCall (
        string CallId
    ) : UiEvent {}
    
    /// <summary>
    /// Read the next page of the call log.
    /// </summary>
    public record LoadMoreCalls: UiEvent {}
    
    
    /// <summary>
    /// Open a contact.
    /// </summary>
    public record OpenContact (
        string ContactId
    ) : UiEvent {}
    
    /// <summary>
    /// Read the next page of contacts.
    /// </summary>
    public record LoadMoreContacts: UiEvent {}
    
    
    /// <summary>
    /// Open the devices list, from the account screen.
    /// </summary>
    public record OpenDevices: UiEvent {}
    
    
    /// <summary>
    /// Ask before signing a device out.
    /// </summary>
    public record AskSignOutDevice (
        string DeviceId
    ) : UiEvent {}
    
    /// <summary>
    /// Ask before signing out every device.
    /// </summary>
    public record AskSignOutEverywhere: UiEvent {}
    
    
    /// <summary>
    /// Answer the devices screen's question yes.
    /// </summary>
    public record ConfirmDevices: UiEvent {}
    
    
    /// <summary>
    /// Answer it no.
    /// </summary>
    public record CancelDevices: UiEvent {}
    
    
    /// <summary>
    /// Put away the devices screen's failure and notes.
    /// </summary>
    public record DismissDevicesNotices: UiEvent {}
    
    
    /// <summary>
    /// Open the account deletion page in the browser.
    /// </summary>
    public record DeleteAccount: UiEvent {}
    
    
    /// <summary>
    /// Report AI-generated content: raises a support request without leaving
    /// the screen. Its progress is [`ShellView::report`](crate::ShellView::report).
    /// </summary>
    public record Report (
        ReportTarget Target,
        string Note
    ) : UiEvent {}
    
    /// <summary>
    /// Put away a report's outcome.
    /// </summary>
    public record DismissReport: UiEvent {}
    
    
    /// <summary>
    /// Open the dialler.
    /// </summary>
    public record OpenDialer: UiEvent {}
    
    
    /// <summary>
    /// The dialler's number changed: what the box holds now, exactly as typed.
    /// </summary>
    public record DialerEdit (
        string Number
    ) : UiEvent {}
    
    /// <summary>
    /// The dialler's "Call" (or Enter in its box).
    /// </summary>
    public record Dial: UiEvent {}
    
    
    /// <summary>
    /// Call `number` from anywhere (a call's or a contact's "Call back"): the
    /// dialler is given the number, then dialled. Two core events.
    /// </summary>
    public record CallNumber (
        string Number
    ) : UiEvent {}
    
    /// <summary>
    /// Hang up the call under way, or abandon a dial on its way.
    /// </summary>
    public record HangUp: UiEvent {}
    
    
    /// <summary>
    /// Put an ended call's summary away.
    /// </summary>
    public record DismissCall: UiEvent {}
    
    
    /// <summary>
    /// Answer the call ringing.
    /// </summary>
    public record Answer (
        string CallId
    ) : UiEvent {}
    
    /// <summary>
    /// Decline it. Nothing is sent to the service.
    /// </summary>
    public record Decline (
        string CallId
    ) : UiEvent {}
    
    /// <summary>
    /// Put an ended ring's line away.
    /// </summary>
    public record DismissRing: UiEvent {}
    
    
    /// <summary>
    /// Turn the microphone on or off, during a call.
    /// </summary>
    public record Microphone (
        bool On
    ) : UiEvent {}
    
    /// <summary>
    /// The account screen's "Ring on this computer".
    /// </summary>
    public record SetRingOnThisComputer (
        bool On
    ) : UiEvent {}
    

    
}

